#include <iostream>
#include <vector>

// Recursive helper function
int binarySearchHelper(const std::vector<int>& list, int key, int low, int high) {
    if (low > high) {
        return -low - 1; // Not found; returns insertion point encoded as negative
    }

    int mid = low + (high - low) / 2; // Safe midpoint calculation

    if (key < list[mid]) {
        return binarySearchHelper(list, key, low, mid - 1);
    } else if (key == list[mid]) {
        return mid; // Match found
    } else {
        return binarySearchHelper(list, key, mid + 1, high);
    }
}

// Public interface function
int binarySearch(const std::vector<int>& list, int key) {
    return binarySearchHelper(list, key, 0, static_cast<int>(list.size()) - 1);
}

int main() {
    std::vector<int> numbers = {2, 4, 7, 10, 11, 45, 50, 59, 60, 66, 69, 70, 79};

    int idx1 = binarySearch(numbers, 2);
    int idx2 = binarySearch(numbers, 11);
    int idx3 = binarySearch(numbers, 12);

    std::cout << "binarySearch(numbers, 2) returns " << idx1 << "\n";
    std::cout << "binarySearch(numbers, 11) returns " << idx2 << "\n";
    std::cout << "binarySearch(numbers, 12) returns " << idx3 << "\n";

    return 0;
}

#include <iostream>

// Recursive function to solve Towers of Hanoi
void moveDisks(int n, char fromTower, char toTower, char auxTower) {
    if (n == 1) { // Base case: stopping condition
        std::cout << "Move disk " << n << " from " << fromTower << " to " << toTower << "\n";
    } else {
        // Step 1: Move n - 1 disks from fromTower to auxTower
        moveDisks(n - 1, fromTower, auxTower, toTower);

        // Step 2: Move disk n from fromTower to toTower
        std::cout << "Move disk " << n << " from " << fromTower << " to " << toTower << "\n";

        // Step 3: Move n - 1 disks from auxTower to toTower
        moveDisks(n - 1, auxTower, toTower, fromTower);
    }
}

int main() {
    int n = 3; // Demonstration with 3 disks
    std::cout << "Solving Towers of Hanoi for " << n << " disks:\n";
    moveDisks(n, 'A', 'B', 'C');
    return 0;
}
